import sys
from collections import Counter

input = sys.stdin.read
data = input().split()

n = int(data[0])
ribbons = data[1:4]

def max_beauty(ribbon, n):
    length = len(ribbon)
    counter = Counter(ribbon)
    max_freq = max(counter.values())
    if n == 1 and max_freq == length:
        return length - 1
    else:
        return min(length, max_freq + n)

beauties = [max_beauty(ribbon, n) for ribbon in ribbons]

max_beauty_value = max(beauties)
